import{_ as i,o as t,c as a,ag as e}from"./chunks/framework.DMXcdKmJ.js";const F=JSON.parse('{"title":"网络与端口清单","description":"为维护人员列出用户访问、节点后台通信与外部数据连接的方向，以及 Ubuntu 24 UFW 入口示例。","frontmatter":{"title":"网络与端口清单","description":"为维护人员列出用户访问、节点后台通信与外部数据连接的方向，以及 Ubuntu 24 UFW 入口示例。","status":"reviewed","kind":"reference"},"headers":[],"relativePath":"zh/reference/network-ports.md","filePath":"zh/参考资料/网络与端口清单.md"}'),d={name:"zh/reference/network-ports.md"};function h(n,s,l,p,o,k){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="网络与端口清单" tabindex="-1">网络与端口清单 <a class="header-anchor" href="#网络与端口清单" aria-label="Permalink to &quot;网络与端口清单&quot;">​</a></h1><p>本页供<strong>服务器维护人员和网络管理员</strong>查询。普通使用者先看<a href="/induframe-docs/zh/installation/network.html">配置网络与防火墙</a>，不必先理解集群内部端口。</p><p>规则要写在正确的目标服务器上：入站是别人连接进来，出站是本机连接出去。每条规则记录来源、目标、协议、实际端口及用途；返回流量也要符合所在网络的规则。</p><p><strong>入口端口以实际配置为准，默认值不是固定要求。</strong> 中心管理端口在安装时可自定义；环境入口和独立入口由各自页面设置。修改过的端口替换本页示例中的默认值，不要新旧端口一起开放。</p><h2 id="用户访问入口" tabindex="-1">用户访问入口 <a class="header-anchor" href="#用户访问入口" aria-label="Permalink to &quot;用户访问入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>谁连接 → 连接到哪里</th><th>端口</th><th>允许范围</th></tr></thead><tbody><tr><td>平台管理员 → 中心管理地址</td><td>默认 <code>18100/TCP</code>，HTTP</td><td>可信管理网络；路径含 <code>/admin/</code>，不映射公网</td></tr><tr><td>平台使用者 → 中心公共地址</td><td>当前交互安装默认 <code>443/TCP</code>，HTTPS</td><td>实际需要使用平台的来源，可仅限企业内网或 VPN</td></tr><tr><td>工程使用者 → 环境入口所在节点</td><td>页面中设置的环境入口 <code>TCP</code> 端口</td><td>需要使用该环境下工程的人，保留完整工程路径</td></tr><tr><td>工程使用者 → 独立部署所在节点</td><td>工程部署中设置的独立 <code>TCP</code> 端口</td><td>仅在启用“节点直连”时需要</td></tr><tr><td>维护人员 → 被管理服务器</td><td>实际 SSH 端口，常见 <code>22/TCP</code></td><td>指定管理来源，修改其他规则前先保留此通道</td></tr></tbody></table><p>只使用环境入口时，不需为每个工程另开独立端口。同一台服务器上的端口不可随意重复占用；页面允许填写的 <code>1024–65535</code> 不是应整体开放的范围，也不需要为了这些入口放行整个 <code>30000–32767</code>。</p><p>交互安装当前使用 HTTPS。技术部署资料中的 HTTP <code>18101</code> 不是所有用户都应额外开放的端口，实际以本次安装结果为准。</p><h2 id="中心与接入节点的后台通信" tabindex="-1">中心与接入节点的后台通信 <a class="header-anchor" href="#中心与接入节点的后台通信" aria-label="Permalink to &quot;中心与接入节点的后台通信&quot;">​</a></h2><p>以下按当前中心 IPv4 安装方式及默认跨节点网络整理，<strong>不是公网开放清单</strong>。中心也是集群成员，节点之间要双向具备相应连接条件。</p><table tabindex="0"><thead><tr><th>发起方 → 接收方</th><th>协议与端口</th><th>用途及限制</th></tr></thead><tbody><tr><td>接入节点 → 中心公共地址</td><td>默认 <code>443/TCP</code>，以下载包提供的中心地址为准</td><td>节点登记、心跳和平台交互；不使用管理入口代替</td></tr><tr><td>接入节点 → 中心内网地址</td><td><code>6443/TCP</code></td><td>加入并连接 K3s 集群，仅允许实际节点和获准管理来源</td></tr><tr><td>接入节点 → 中心内网仓库地址</td><td>默认 <code>5000/TCP</code>，以中心下发配置为准</td><td>镜像下载；协议、证书和权限也须匹配，不能因证书错误改成明文</td></tr><tr><td>接入节点 → 中心下发校时地址</td><td><code>123/UDP</code></td><td>校时；服务端还须允许节点来源，防火墙放行不等于服务已授权</td></tr><tr><td>中心及各节点 → 其他集群成员</td><td><code>8472/UDP</code></td><td>默认跨节点容器网络，严格限本集群成员，禁止公网访问</td></tr><tr><td>中心及各节点 → 其他集群成员</td><td><code>10250/TCP</code></td><td>节点指标与 kubelet 访问，限实际集群成员及明确获准来源</td></tr></tbody></table><p>节点显示“在线”不代表上述连接全部正常。TCP 探测成功不能证明 UDP 校时或跨节点网络正常，应结合节点加入、镜像拉取、校时状态和真实跨机业务确认。</p><p>当前普通接入不需要向外开放 <code>2379–2380/TCP</code>，也不因为使用 K3s 就开放 <code>51820–51821/UDP</code> 或 <code>5001/TCP</code> 等可选功能端口。增加接入节点不等于本产品已具备或已验证高可用部署。</p><h2 id="内部网络与不应外露的服务" tabindex="-1">内部网络与不应外露的服务 <a class="header-anchor" href="#内部网络与不应外露的服务" aria-label="Permalink to &quot;内部网络与不应外露的服务&quot;">​</a></h2><ul><li>当前容器网段为 <code>10.42.0.0/16</code>，服务网段为 <code>10.43.0.0/16</code>。必须与企业、VPN、设备及其他集群网络错开；用户电脑通常不需要直接连接这些地址。</li><li>保留防火墙时，维护人员还应核对这些内部网段的来源与转发策略；不能只加普通主机入站规则，也不能一概放开全部转发。</li><li>内部 API、数据与计算服务的 <code>18101</code>、<code>18102</code>、<code>18103</code>，以及内置数据库、缓存、消息和对象服务的 <code>5432</code>、<code>18379</code>、<code>1883</code>、<code>8333</code>，不是供用户逐个访问的公网端口。</li><li>编辑器、AI 和页面预览使用平台提供的代理入口，不把每个开发进程的内部端口映射出去。</li><li>安装器会准备运行环境所需的容器网络规则，但不等于替用户配置好了 UFW、云安全组或机房防火墙。</li></ul><p>K3s 通用规则可参考<a href="https://docs.k3s.io/installation/requirements#networking" target="_blank" rel="noreferrer">官方网络要求</a>，实际仅采用本产品启用的功能与现场需要的范围，不照搬整张通用开放表。</p><h2 id="ubuntu-24-的-ufw-入口示例" tabindex="-1">Ubuntu 24 的 UFW 入口示例 <a class="header-anchor" href="#ubuntu-24-的-ufw-入口示例" aria-label="Permalink to &quot;Ubuntu 24 的 UFW 入口示例&quot;">​</a></h2><p>以下仅演示<strong>用户入口规则</strong>，不是一套可直接启用的完整集群防火墙策略。它们不替代前面的后台通信、内部转发及业务出口核对，也不代表现场 UFW 与安全组组合已经验证。</p><div class="warning custom-block"><p class="custom-block-title">操作前先确认</p><p>命令由维护人员在目标服务器终端执行，示例 IP 都是虚构地址，必须先替换。保留当前 SSH 会话及可用控制台，先允许自己的实际 SSH 来源和端口，不清空已有规则。</p><p>平台部分端口由容器转发提供，可能不经过普通主机入站规则。UFW 的单条来源限制不能作为已隔离证明；还要设置上游防火墙或云安全组，并从允许、拒绝来源两侧核验。已有全来源允许规则也不会被新规则自动撤销。</p></div><h3 id="先查看-不急着启用" tabindex="-1">先查看，不急着启用 <a class="header-anchor" href="#先查看-不急着启用" aria-label="Permalink to &quot;先查看，不急着启用&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verbose</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> numbered</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> added</span></span></code></pre></div><p><code>active</code> 表示已启用，<code>inactive</code> 表示未启用；没有 UFW 也不代表没有其他防护。先记录原有规则与默认策略，已有其他业务时不要直接更改全局策略。</p><h3 id="中心服务器示例" tabindex="-1">中心服务器示例 <a class="header-anchor" href="#中心服务器示例" aria-label="Permalink to &quot;中心服务器示例&quot;">​</a></h3><p>假设中心为 <code>10.20.0.10</code>，管理网络为 <code>10.30.0.0/24</code>，平台使用者网络为 <code>10.40.0.0/24</code>，SSH 端口为 <code>22</code>。<code>/24</code> 表示一个网段，只允许一台管理电脑时可改成它实际来源 IP 的 <code>/32</code>。</p><p>先允许 SSH，再允许管理与平台入口；在中心服务器执行自己核对过的对应规则：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.30.0.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.20.0.10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.30.0.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.20.0.10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 18100</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.30.0.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.20.0.10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 443</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.40.0.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.20.0.10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 443</span></span></code></pre></div><p>上述目标是中心的示例内网地址。如果入口实际上使用其他网卡地址，维护人员须针对真实目标配置；来源也按服务器实际看到的地址填写。</p><h3 id="环境和独立入口示例" tabindex="-1">环境和独立入口示例 <a class="header-anchor" href="#环境和独立入口示例" aria-label="Permalink to &quot;环境和独立入口示例&quot;">​</a></h3><p>假设环境入口在 <code>10.20.0.11</code>，端口为 <code>17800</code>；需要让 <code>10.40.0.0/24</code> 的使用者访问，则在<strong>这台入口节点</strong>添加：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.40.0.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.20.0.11</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17800</span></span></code></pre></div><p>如果某个工程还在 <code>10.20.0.12</code> 启用了独立端口 <code>17810</code>，才在<strong>这台独立部署节点</strong>另外添加：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.40.0.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.20.0.12</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17810</span></span></code></pre></div><p>两个端口都只是例子。不要把规则全部加在中心服务器，也不要为未启用的独立访问预先开放一批端口。</p><h3 id="规则生效与复核" tabindex="-1">规则生效与复核 <a class="header-anchor" href="#规则生效与复核" aria-label="Permalink to &quot;规则生效与复核&quot;">​</a></h3><p>UFW 已启用时，新增规则通常立即生效。原先未启用时，<strong>只有完整核对 SSH、其他业务、节点后台通信与内部转发，并确保控制台能够恢复之后</strong>，维护人员才启用：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verbose</span></span></code></pre></div><p>保留原会话，另开终端建立新的 SSH 连接；再从真正的使用者电脑打开页面，并从非白名单的受控测试来源验证敏感端口无法访问。不能只测服务器自己，也不能把规则保存成功当成访问验收。</p><p>改端口、删除节点或卸载后，按用途记录清理自己的 UFW 与安全组规则。使用编号删除时每删一条就重新查看，因为编号可能变化；不批量清空，不误删 SSH、共享集群或其他服务的规则。</p><h2 id="连接外部数据库、设备和-ai-时" tabindex="-1">连接外部数据库、设备和 AI 时 <a class="header-anchor" href="#连接外部数据库、设备和-ai-时" aria-label="Permalink to &quot;连接外部数据库、设备和 AI 时&quot;">​</a></h2><p>多数接入源是<strong>平台中的程序向外连接目标服务</strong>，不是让外部服务器连接进平台。不能把数据库连接失败误处理成在中心开放数据库端口。</p><table tabindex="0"><thead><tr><th>要使用的外部服务</th><th>常见目标端口示例</th><th>由谁确认</th></tr></thead><tbody><tr><td>MySQL、PostgreSQL、SQL Server</td><td>常见 <code>3306/TCP</code>、<code>5432/TCP</code>、<code>1433/TCP</code></td><td>数据库管理员提供实际地址、端口、账号及允许来源</td></tr><tr><td>Redis、MQTT</td><td>Redis 常见 <code>6379/TCP</code>；MQTT 常见 <code>1883/TCP</code> 或 TLS <code>8883/TCP</code></td><td>以接入源配置和外部服务的实际监听为准</td></tr><tr><td>Kafka</td><td>常见 <code>9092/TCP</code>，实际可能不同</td><td>引导地址与返回的各消息节点地址都要能解析、访问</td></tr><tr><td>HTTP、WebSocket、TDengine</td><td>按实际 URL；常见 <code>80/TCP</code>、<code>443/TCP</code>，TDengine REST 常见 <code>6041/TCP</code></td><td>只连接配置中的目标服务，不根据协议名称猜另一组端口</td></tr><tr><td>工业设备</td><td>按驱动与设备设置；如 Modbus TCP 常见 <code>502/TCP</code>、OPC UA 常见 <code>4840/TCP</code></td><td>现场设备负责人确认协议、目标及权限</td></tr><tr><td>AI 模型服务</td><td>常见 HTTPS <code>443/TCP</code>；自建服务按实际端口</td><td>确认开发环境能到达模型地址，DNS、证书、API Key 和必要代理正确</td></tr><tr><td>DNS 解析服务</td><td><code>53/UDP</code> 与 <code>53/TCP</code></td><td>使用组织批准的解析服务，主机与容器都要能正常解析</td></tr></tbody></table><p>这些是常见值，不是必须全部放行的列表，也不扩大已测试的数据库、设备或模型兼容范围。使用了哪一种，才允许相应程序到那个实际目标。</p><p>发起连接的位置可能是采集节点、开发容器或运行容器。远端看到的来源还可能经过出口地址转换，须由网络管理员确认，不把使用者电脑或某个容器地址直接猜填到远端白名单。</p><p>域名、证书和目标权限也要一起核对；电脑浏览器能访问模型或数据库所在网络，不代表服务器里的程序也能访问。限制出口时按具体服务和组织批准的出口方式处理，不放开整个互联网来解决一次失败。</p><p>下一步：<a href="/induframe-docs/zh/installation/network.html">按用户入口配置网络</a> · <a href="/induframe-docs/zh/guide/runtime-data-troubleshooting.html">运行问题排查</a>。</p>`,45)])])}const c=i(d,[["render",h]]);export{F as __pageData,c as default};
